// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, type(uint128).max);

        // fund the test contract (the owner of c) and deposit `amount` via the fallback
        vm.deal(address(this), amount + 1);
        (bool dep, ) = address(c).call{value: amount}("");
        assertTrue(dep);

        uint256 preBal = address(c).balance;
        uint256 ownerBefore = address(this).balance;

        // owner (address(this) == msg.sender at deployment) withdraws everything
        bool ok = true;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        uint256 ownerAfter = address(this).balance;

        // Rule: a successful withdrawAll hands the owner exactly the full prior balance
        // and drains the contract completely (balance becomes 0).
        assertTrue(ok && address(c).balance == 0 && (ownerAfter - ownerBefore) == preBal);
    }

    receive() external payable {}
}
